mapper.select:
SELECT
    DATE_FORMAT(visit_time, '%Y-%m-%d') AS visit_date,
    DATE_FORMAT(visit_time, '%m-%d') AS visit_label,
    COUNT(1) AS visit_count
FROM `page_visit_log`
WHERE page_code = #{pageCode}
  AND user_id = #{userId}
  AND visit_time >= #{startTime}
  AND visit_time < #{endTime}
GROUP BY DATE(visit_time), DATE_FORMAT(visit_time, '%Y-%m-%d'), DATE_FORMAT(visit_time, '%m-%d')
ORDER BY DATE(visit_time) ASC
